<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class CandidateProfile extends Model{protected $fillable=['user_id','first_name','last_name','phone','phone_country_code','country_code','state','city','locality','job_search_status','search_appearances','recruiter_actions','profile_views_count','phone_confirmed_at','guidance_completed_at','salary_currency','current_salary_currency','expected_salary_currency','address','avatar_path','headline','bio','current_company','current_designation','experience_years','current_salary','expected_salary','notice_period','location','preferred_role','education','profile_completion'];protected $casts=['current_salary'=>'decimal:2','expected_salary'=>'decimal:2','profile_completion'=>'integer','search_appearances'=>'integer','recruiter_actions'=>'integer','profile_views_count'=>'integer','phone_confirmed_at'=>'datetime','guidance_completed_at'=>'datetime'];public function user(){return $this->belongsTo(User::class);}public function resumes(){return $this->hasMany(Resume::class);}public function getAvatarUrlAttribute(){return $this->avatar_path?asset('storage/'.$this->avatar_path):null;}}
